CREATE OR REPLACE FUNCTION public.feya_fn_apply_content_prechecks_v1(p_draft_id uuid, p_actor text DEFAULT 'system:content_prechecks_v1'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_draft public.feya_commerce_seo_pack_drafts_v1%rowtype;
  v_result jsonb;
  v_similarity jsonb;
  v_alt jsonb;
  v_component jsonb;
  v_similarity_qa text;
  v_alt_qa text;
  v_component_qa text;
begin
  select *
    into v_draft
  from public.feya_commerce_seo_pack_drafts_v1 d
  where d.id=p_draft_id
    and d.archived_at is null
  for update;

  if not found then
    raise exception 'Active SEO pack draft not found: %',p_draft_id;
  end if;

  v_result := public.feya_fn_preview_content_prechecks_v1(p_draft_id);
  v_similarity := v_result -> 'similarity';
  v_alt := v_result -> 'image_alt';
  v_component := v_result -> 'component_claim';

  v_similarity_qa := case
    when v_similarity ->> 'status' = 'pass' then 'pass'
    else 'warning'
  end;

  v_alt_qa := case
    when v_alt ->> 'status' = 'pass' then 'pass'
    else 'warning'
  end;

  v_component_qa := case
    when v_component ->> 'status' = 'pass' then 'pass'
    else 'warning'
  end;

  update public.feya_commerce_seo_pack_drafts_v1 d
  set similarity_check_snapshot=v_similarity,
      qa_self_report=
        jsonb_set(
          jsonb_set(
            jsonb_set(
              jsonb_set(
                coalesce(d.qa_self_report,'{}'::jsonb),
                '{similarity_cannibalization}',
                to_jsonb(v_similarity_qa),
                true
              ),
              '{textual_similarity_precheck}',
              v_similarity,
              true
            ),
            '{image_alt_truth}',
            to_jsonb(v_alt_qa),
            true
          ),
          '{component_claim_truth}',
          to_jsonb(v_component_qa),
          true
        )
        || jsonb_build_object(
          'image_alt_precheck',v_alt,
          'component_claim_precheck',v_component
        ),
      updated_at=now()
  where d.id=p_draft_id;

  insert into public.feya_commerce_seo_pack_draft_events_v1 (
    draft_id,canonical_product_id,event_type,from_status,to_status,
    actor,note,payload
  )
  values (
    v_draft.id,v_draft.canonical_product_id,'similarity_checked',
    v_draft.status,v_draft.status,p_actor,
    'Deterministic textual similarity precheck completed',
    v_similarity
  );

  insert into public.feya_commerce_seo_pack_draft_events_v1 (
    draft_id,canonical_product_id,event_type,from_status,to_status,
    actor,note,payload
  )
  values (
    v_draft.id,v_draft.canonical_product_id,'image_alt_checked',
    v_draft.status,v_draft.status,p_actor,
    'Deterministic image ALT truth precheck completed',
    v_alt
  );

  insert into public.feya_commerce_seo_pack_draft_events_v1 (
    draft_id,canonical_product_id,event_type,from_status,to_status,
    actor,note,payload
  )
  values (
    v_draft.id,v_draft.canonical_product_id,'validation_checked',
    v_draft.status,v_draft.status,p_actor,
    'Deterministic component-inclusion claim precheck completed',
    v_component
  );

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.feya_fn_preview_content_prechecks_v1(p_draft_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_draft public.feya_commerce_seo_pack_drafts_v1%rowtype;
  v_text text;
  v_tokens text[];
  v_nearest_draft_id uuid;
  v_nearest_product_id uuid;
  v_max_score numeric := 0;
  v_similarity_status text;
  v_similarity_snapshot jsonb;
  v_alts jsonb;
  v_primary_alt text;
  v_alt_invalid_count integer := 0;
  v_alt_status text;
  v_alt_snapshot jsonb;
  v_component_snapshot jsonb;
  v_component_status text;
begin
  select *
    into v_draft
  from public.feya_commerce_seo_pack_drafts_v1 d
  where d.id=p_draft_id
    and d.archived_at is null;

  if not found then
    raise exception 'Active SEO pack draft not found: %',p_draft_id;
  end if;

  v_text := coalesce(v_draft.seo_title,'') || ' ' ||
            coalesce(v_draft.h1,'') || ' ' ||
            coalesce(v_draft.intro,'');
  v_tokens := public.feya_fn_content_token_set_v1(v_text);

  with latest_other as (
    select distinct on (d.canonical_product_id)
      d.id,
      d.canonical_product_id,
      public.feya_fn_content_token_set_v1(
        coalesce(d.seo_title,'') || ' ' ||
        coalesce(d.h1,'') || ' ' ||
        coalesce(d.intro,'')
      ) as tokens
    from public.feya_commerce_seo_pack_drafts_v1 d
    where d.archived_at is null
      and d.canonical_product_id <> v_draft.canonical_product_id
    order by d.canonical_product_id,d.created_at desc
  ),
  scored as (
    select
      l.id,
      l.canonical_product_id,
      public.feya_fn_content_jaccard_v1(v_tokens,l.tokens) as score
    from latest_other l
  )
  select id,canonical_product_id,score
    into v_nearest_draft_id,v_nearest_product_id,v_max_score
  from scored
  order by score desc nulls last,id
  limit 1;

  v_max_score := coalesce(v_max_score,0);

  v_similarity_status := case
    when v_max_score >= 0.60 then 'needs_review'
    when v_max_score >= 0.50 then 'warning'
    else 'pass'
  end;

  v_similarity_snapshot := jsonb_build_object(
    'status',v_similarity_status,
    'scope','content_textual_similarity',
    'method','token_jaccard_v1',
    'score',round(v_max_score,4),
    'pass_threshold_lt',0.50,
    'warning_threshold_gte',0.50,
    'review_threshold_gte',0.60,
    'nearest_draft_id',v_nearest_draft_id,
    'nearest_product_id',v_nearest_product_id,
    'not_query_cannibalization',true,
    'query_page_conflict_owner','OSPM'
  );

  v_alts := coalesce(v_draft.image_alt_candidates,'[]'::jsonb);
  v_primary_alt := nullif(btrim(v_draft.product_truth_snapshot ->> 'primary_image_alt'),'');

  if jsonb_typeof(v_alts) <> 'array' then
    v_alt_invalid_count := 1;
  elsif jsonb_array_length(v_alts)=0 then
    v_alt_invalid_count := 0;
  else
    select count(*)::integer
      into v_alt_invalid_count
    from jsonb_array_elements(v_alts) e
    where
      coalesce(e ->> 'image_role','') <> 'primary'
      or nullif(btrim(e ->> 'alt_text'),'') is null
      or v_primary_alt is null
      or btrim(e ->> 'alt_text') <> v_primary_alt;
  end if;

  v_alt_status := case
    when jsonb_typeof(v_alts) <> 'array' then 'needs_review'
    when jsonb_array_length(v_alts)=0 then 'pass'
    when v_alt_invalid_count=0 then 'pass'
    else 'needs_review'
  end;

  v_alt_snapshot := jsonb_build_object(
    'status',v_alt_status,
    'method','product_truth_primary_alt_exact_v1',
    'candidate_count',
      case when jsonb_typeof(v_alts)='array' then jsonb_array_length(v_alts) else null end,
    'invalid_candidate_count',v_alt_invalid_count,
    'primary_image_alt_available',v_primary_alt is not null,
    'empty_candidate_policy','pass_no_sco_alt_claims_media_alt_is_separate'
  );

  v_component_snapshot := public.feya_fn_component_claim_precheck_v1(p_draft_id);
  v_component_status := coalesce(v_component_snapshot ->> 'status','needs_review');

  return jsonb_build_object(
    'draft_id',v_draft.id,
    'canonical_product_id',v_draft.canonical_product_id,
    'similarity',v_similarity_snapshot,
    'image_alt',v_alt_snapshot,
    'component_claim',v_component_snapshot,
    'overall_status',case
      when v_similarity_status='needs_review'
        or v_alt_status='needs_review'
        or v_component_status='needs_review'
        then 'needs_review'
      when v_similarity_status='warning' then 'warning'
      else 'pass'
    end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.feya_fn_record_content_cqa_result_v1(p_draft_id uuid, p_expected_cqa_status text, p_cqa_status text, p_result jsonb, p_reviewer text, p_policy_version text)
 RETURNS TABLE(ok boolean, draft_id uuid, cqa_status text, cqa_reviewed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row public.feya_commerce_seo_pack_drafts_v1%rowtype;
  v_reviewed_at timestamptz := now();
begin
  if p_cqa_status not in (
    'pass',
    'pass_with_warnings',
    'revision_required',
    'domain_review_required',
    'reject'
  ) then
    raise exception 'Unsupported CQA status: %', p_cqa_status;
  end if;

  if nullif(btrim(coalesce(p_reviewer,'')),'') is null then
    raise exception 'CQA reviewer is required';
  end if;

  if nullif(btrim(coalesce(p_policy_version,'')),'') is null then
    raise exception 'CQA policy version is required';
  end if;

  if p_result is null or jsonb_typeof(p_result) <> 'object' then
    raise exception 'CQA result must be a JSON object';
  end if;

  select *
    into v_row
  from public.feya_commerce_seo_pack_drafts_v1 d
  where d.id=p_draft_id
    and d.archived_at is null
  for update;

  if not found then
    raise exception 'Active SEO pack draft not found: %', p_draft_id;
  end if;

  if v_row.cqa_status <> p_expected_cqa_status then
    raise exception 'Stale CQA state for draft %: expected %, current %',
      p_draft_id,p_expected_cqa_status,v_row.cqa_status;
  end if;

  update public.feya_commerce_seo_pack_drafts_v1 d
  set cqa_status=p_cqa_status,
      cqa_result_snapshot=p_result,
      cqa_reviewer=p_reviewer,
      cqa_policy_version=p_policy_version,
      cqa_reviewed_at=v_reviewed_at,
      updated_at=now()
  where d.id=p_draft_id;

  insert into public.feya_commerce_seo_pack_draft_events_v1 (
    draft_id,
    canonical_product_id,
    event_type,
    from_status,
    to_status,
    actor,
    note,
    payload
  )
  values (
    v_row.id,
    v_row.canonical_product_id,
    'cqa_checked',
    v_row.status,
    v_row.status,
    p_reviewer,
    'Independent CQA review recorded',
    jsonb_build_object(
      'cqa_status',p_cqa_status,
      'policy_version',p_policy_version,
      'result',p_result
    )
  );

  return query
  select true,p_draft_id,p_cqa_status,v_reviewed_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.feya_fn_record_keyword_cleanup_review_recommendation_v1(p_cleanup_id bigint, p_expected_review_status text, p_recommendation text, p_recommended_keyword text, p_recommended_page_level text, p_recommended_intent text, p_issues_json jsonb, p_reason text, p_model_name text, p_prompt_version text, p_run_id uuid, p_source_snapshot jsonb)
 RETURNS TABLE(recommendation_id uuid, created_new boolean, recommendation text, review_risk text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cleanup public.feya_commerce_seo_keyword_ai_cleanup_v1%rowtype;
  v_risk public.feya_commerce_v_keyword_cleanup_review_risk_v1%rowtype;
  v_hash text;
  v_existing public.feya_commerce_seo_keyword_cleanup_review_recommendations_v1%rowtype;
  v_row public.feya_commerce_seo_keyword_cleanup_review_recommendations_v1%rowtype;
  v_keyword text;
begin
  if p_recommendation not in ('APPROVE','REJECT','HUMAN_REVIEW','HOLD') then
    raise exception 'Unsupported review recommendation: %',p_recommendation;
  end if;

  if nullif(btrim(coalesce(p_reason,'')),'') is null then
    raise exception 'Recommendation reason is required';
  end if;

  if nullif(btrim(coalesce(p_model_name,'')),'') is null then
    raise exception 'Recommendation model is required';
  end if;

  if nullif(btrim(coalesce(p_prompt_version,'')),'') is null then
    raise exception 'Recommendation prompt version is required';
  end if;

  if p_run_id is null then
    raise exception 'Recommendation run id is required';
  end if;

  if p_issues_json is null or jsonb_typeof(p_issues_json) <> 'array' then
    raise exception 'Recommendation issues must be a JSON array';
  end if;

  select *
    into v_cleanup
  from public.feya_commerce_seo_keyword_ai_cleanup_v1 c
  where c.cleanup_id=p_cleanup_id
  for update;

  if not found then
    raise exception 'Keyword cleanup row not found: %',p_cleanup_id;
  end if;

  if v_cleanup.review_status <> p_expected_review_status then
    raise exception 'Stale cleanup review status: expected %, current %',
      p_expected_review_status,v_cleanup.review_status;
  end if;

  if v_cleanup.review_status not in ('pending','needs_review') then
    raise exception 'Cleanup status % is not reviewable',v_cleanup.review_status;
  end if;

  select *
    into v_risk
  from public.feya_commerce_v_keyword_cleanup_review_risk_v1 q
  where q.cleanup_id=p_cleanup_id;

  if not found then
    raise exception 'Cleanup row is not the current pending review candidate';
  end if;

  v_keyword := case
    when p_recommendation='APPROVE' then coalesce(
      nullif(btrim(p_recommended_keyword),''),
      nullif(btrim(v_risk.effective_keyword),'')
    )
    else nullif(btrim(p_recommended_keyword),'')
  end;

  if p_recommendation='APPROVE' and v_keyword is null then
    raise exception 'APPROVE recommendation requires a keyword';
  end if;

  v_hash := md5(
    jsonb_build_object(
      'recommendation',p_recommendation,
      'recommended_keyword',v_keyword,
      'recommended_page_level',p_recommended_page_level,
      'recommended_intent',p_recommended_intent,
      'issues',p_issues_json,
      'reason',p_reason
    )::text
  );

  select *
    into v_existing
  from public.feya_commerce_seo_keyword_cleanup_review_recommendations_v1 r
  where r.cleanup_id=p_cleanup_id
    and r.prompt_version=p_prompt_version
    and r.recommendation_hash=v_hash
  order by r.created_at desc
  limit 1;

  if found then
    return query
    select v_existing.recommendation_id,false,
           v_existing.recommendation,v_existing.review_risk;
    return;
  end if;

  insert into public.feya_commerce_seo_keyword_cleanup_review_recommendations_v1 (
    cleanup_id,keyword_id,keyword_norm,review_risk,recommendation,
    recommended_keyword,recommended_page_level,recommended_intent,
    issues_json,reason,model_name,prompt_version,run_id,
    source_snapshot,recommendation_hash
  )
  values (
    p_cleanup_id,v_cleanup.keyword_id,v_cleanup.keyword_norm,
    v_risk.review_risk,p_recommendation,v_keyword,
    nullif(btrim(p_recommended_page_level),''),
    nullif(btrim(p_recommended_intent),''),
    p_issues_json,p_reason,p_model_name,p_prompt_version,p_run_id,
    coalesce(p_source_snapshot,'{}'::jsonb),v_hash
  )
  returning * into v_row;

  return query
  select v_row.recommendation_id,true,v_row.recommendation,v_row.review_risk;
end;
$function$

CREATE OR REPLACE FUNCTION public.feya_fn_record_page_ownership_proposal_v1(p_query_cluster_id uuid, p_seo_page_id uuid, p_ownership_role text, p_market_code text, p_locale text, p_rationale text, p_evidence_json jsonb, p_model_name text, p_prompt_version text, p_run_id uuid)
 RETURNS TABLE(proposal_id uuid, created_new boolean, proposal_status text, proposal_hash text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cluster public.feya_commerce_seo_query_clusters_v1%rowtype;
  v_page public.feya_commerce_seo_pages_v1%rowtype;
  v_existing public.feya_commerce_seo_page_ownership_proposals_v1%rowtype;
  v_row public.feya_commerce_seo_page_ownership_proposals_v1%rowtype;
  v_hash text;
  v_owner_count integer;
begin
  if p_ownership_role not in ('primary','secondary','support') then
    raise exception 'Unsupported ownership role: %',p_ownership_role;
  end if;

  if nullif(btrim(coalesce(p_model_name,'')),'') is null then
    raise exception 'Model name is required';
  end if;

  if nullif(btrim(coalesce(p_prompt_version,'')),'') is null then
    raise exception 'Prompt version is required';
  end if;

  if p_run_id is null then
    raise exception 'Run id is required';
  end if;

  select *
    into v_cluster
  from public.feya_commerce_seo_query_clusters_v1 c
  where c.query_cluster_id=p_query_cluster_id;

  if not found then
    raise exception 'Query cluster not found: %',p_query_cluster_id;
  end if;

  if v_cluster.cluster_status <> 'approved' then
    raise exception 'Query cluster status % is not eligible for ownership proposal',
      v_cluster.cluster_status;
  end if;

  select *
    into v_page
  from public.feya_commerce_seo_pages_v1 p
  where p.seo_page_id=p_seo_page_id;

  if not found then
    raise exception 'SEO page not found: %',p_seo_page_id;
  end if;

  if v_page.portfolio_status <> 'active' then
    raise exception 'SEO page portfolio status % is not eligible',v_page.portfolio_status;
  end if;

  if v_page.indexation_intent not in ('candidate','indexable') then
    raise exception 'SEO page indexation intent % is not eligible',v_page.indexation_intent;
  end if;

  if p_ownership_role='primary' then
    select count(*)::integer
      into v_owner_count
    from public.feya_commerce_seo_page_query_ownership_v1 o
    where o.query_cluster_id=p_query_cluster_id
      and o.market_code=coalesce(nullif(btrim(p_market_code),''),'US')
      and o.locale=coalesce(nullif(btrim(p_locale),''),'en-US')
      and o.ownership_role='primary'
      and o.ownership_status in ('intended','active','protected')
      and o.effective_to is null;

    if v_owner_count > 0 then
      raise exception 'Query cluster already has an active primary owner for market/locale';
    end if;
  end if;

  v_hash := md5(
    jsonb_build_object(
      'query_cluster_id',p_query_cluster_id,
      'seo_page_id',p_seo_page_id,
      'ownership_role',p_ownership_role,
      'market_code',coalesce(nullif(upper(btrim(p_market_code)),''),'US'),
      'locale',coalesce(nullif(btrim(p_locale),''),'en-US')
    )::text
  );

  select *
    into v_existing
  from public.feya_commerce_seo_page_ownership_proposals_v1 p
  where p.proposal_hash=v_hash
    and p.proposal_status not in ('REJECTED','CANCELLED')
  order by p.created_at desc
  limit 1;

  if found then
    return query
    select v_existing.proposal_id,false,
           v_existing.proposal_status,v_existing.proposal_hash;
    return;
  end if;

  insert into public.feya_commerce_seo_page_ownership_proposals_v1 (
    query_cluster_id,seo_page_id,ownership_role,market_code,locale,
    rationale,evidence_json,proposal_status,model_name,prompt_version,
    run_id,proposal_hash
  )
  values (
    p_query_cluster_id,p_seo_page_id,p_ownership_role,
    coalesce(nullif(upper(btrim(p_market_code)),''),'US'),
    coalesce(nullif(btrim(p_locale),''),'en-US'),
    nullif(btrim(p_rationale),''),
    coalesce(p_evidence_json,'{}'::jsonb),
    'REVIEW',p_model_name,p_prompt_version,p_run_id,v_hash
  )
  returning * into v_row;

  return query
  select v_row.proposal_id,true,v_row.proposal_status,v_row.proposal_hash;
end;
$function$

CREATE OR REPLACE FUNCTION public.feya_fn_record_query_cluster_proposal_v1(p_cluster_label text, p_normalized_intent text, p_intent_type text, p_language_code text, p_market_scope text, p_members_json jsonb, p_rationale text, p_model_name text, p_prompt_version text, p_run_id uuid, p_source_snapshot_json jsonb)
 RETURNS TABLE(proposal_id uuid, proposal_code text, created_new boolean, proposal_status text, proposal_hash text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_member jsonb;
  v_keyword_norm text;
  v_member_role text;
  v_seed_count integer := 0;
  v_ready_count integer;
  v_member_count integer := 0;
  v_hash text;
  v_existing public.feya_commerce_seo_query_cluster_proposals_v1%rowtype;
  v_row public.feya_commerce_seo_query_cluster_proposals_v1%rowtype;
  v_code text;
begin
  if nullif(btrim(coalesce(p_cluster_label,'')),'') is null then
    raise exception 'Cluster label is required';
  end if;

  if nullif(btrim(coalesce(p_normalized_intent,'')),'') is null then
    raise exception 'Normalized intent is required';
  end if;

  if nullif(btrim(coalesce(p_prompt_version,'')),'') is null then
    raise exception 'Prompt version is required';
  end if;

  if nullif(btrim(coalesce(p_model_name,'')),'') is null then
    raise exception 'Model name is required';
  end if;

  if p_run_id is null then
    raise exception 'Run id is required';
  end if;

  if p_members_json is null
     or jsonb_typeof(p_members_json) <> 'array'
     or jsonb_array_length(p_members_json)=0 then
    raise exception 'Proposal members must be a non-empty JSON array';
  end if;

  for v_member in
    select value from jsonb_array_elements(p_members_json)
  loop
    v_keyword_norm := nullif(btrim(v_member ->> 'keyword_norm'),'');
    v_member_role := coalesce(nullif(btrim(v_member ->> 'member_role'),''),'member');

    if v_keyword_norm is null then
      raise exception 'Proposal member missing keyword_norm';
    end if;

    if v_member_role not in ('seed','member') then
      raise exception 'Unsupported proposal member role: %',v_member_role;
    end if;

    if v_member_role='seed' then
      v_seed_count := v_seed_count + 1;
    end if;

    select count(*)::integer
      into v_ready_count
    from public.feya_commerce_v_query_cluster_proposal_candidates_v1 c
    where c.keyword_norm=v_keyword_norm
      and c.proposal_candidate_status='READY_FOR_CLUSTER_PROPOSAL';

    if v_ready_count = 0 then
      raise exception 'Keyword % is not a human-approved unclustered proposal candidate',v_keyword_norm;
    end if;

    v_member_count := v_member_count + 1;
  end loop;

  if v_seed_count <> 1 then
    raise exception 'Query cluster proposal must contain exactly one seed member; found %',v_seed_count;
  end if;

  v_hash := md5(
    jsonb_build_object(
      'cluster_label',lower(btrim(p_cluster_label)),
      'normalized_intent',lower(btrim(p_normalized_intent)),
      'intent_type',coalesce(lower(btrim(p_intent_type)),''),
      'language_code',coalesce(lower(btrim(p_language_code)),'en'),
      'market_scope',coalesce(upper(btrim(p_market_scope)),'GLOBAL'),
      'members',p_members_json
    )::text
  );

  select *
    into v_existing
  from public.feya_commerce_seo_query_cluster_proposals_v1 p
  where p.proposal_hash=v_hash
    and p.proposal_status not in ('REJECTED','CANCELLED')
  order by p.created_at desc
  limit 1;

  if found then
    return query
    select v_existing.proposal_id,v_existing.proposal_code,false,
           v_existing.proposal_status,v_existing.proposal_hash;
    return;
  end if;

  v_code := 'QCP-' || to_char(clock_timestamp(),'YYYYMMDD-HH24MISS') || '-' ||
            upper(substr(replace(gen_random_uuid()::text,'-',''),1,6));

  insert into public.feya_commerce_seo_query_cluster_proposals_v1 (
    proposal_code,cluster_label,normalized_intent,intent_type,
    language_code,market_scope,proposed_members_json,rationale,
    proposal_status,model_name,prompt_version,run_id,
    source_snapshot_json,proposal_hash
  )
  values (
    v_code,btrim(p_cluster_label),lower(btrim(p_normalized_intent)),
    nullif(lower(btrim(p_intent_type)),''),
    coalesce(nullif(lower(btrim(p_language_code)),''),'en'),
    coalesce(nullif(upper(btrim(p_market_scope)),''),'GLOBAL'),
    p_members_json,nullif(btrim(p_rationale),''),
    'REVIEW',p_model_name,p_prompt_version,p_run_id,
    coalesce(p_source_snapshot_json,'{}'::jsonb),v_hash
  )
  returning * into v_row;

  return query
  select v_row.proposal_id,v_row.proposal_code,true,
         v_row.proposal_status,v_row.proposal_hash;
end;
$function$
